#include <stdio.h>
#include <queue>
#include <cctype>
#include <vector>
#include <cstring>
using namespace std;

const int BIG = 12345678;

struct Point {
    int r, c, idx;
};

struct Holder {
    int nums[1000];
    int sz;
    bool used;
};

Holder cells[100][100];
vector<int> graph[1000];
int N, T;
int L[1000], R[1000], seen[1000];
char g1[1000][1000], g2[1000][1000];
int D1[1000][1000], D2[1000][1000];
queue<Point> Q;

void BFS1(Point s);
void BFS2(Point s);
int bipartite(int m);
bool augment(int u);

int main() {
    int i, j, k, l;
    Point p, q;

    scanf("%d %d", &N, &T);

    for (i = 0; i <= N; ++i)
        for (j = 0; j <= N; ++j)
            D1[i][j] = BIG;

    for (i = 0; i < N; ++i) scanf("%s", g1[i]);
    for (i = 0; i < N; ++i) scanf("%s", g2[i]);

    for (i = 0; i < N; ++i)
        for (j = 0; j < N; ++j)
            if (g1[i][j] == 'Z') {
                p.r = i; p.c = j;
                BFS1(p);
            }

    int cnt = 1;
    for (i = 0; i < N; ++i)
        for (j = 0; j < N; ++j)
            if (isdigit(g2[i][j])) {
                k = g2[i][j] - '0';
                if (k > 0) cells[i][j].used = true;
                cells[i][j].sz = k;
                for (l = 1; l <= k; ++l)
                    cells[i][j].nums[l] = cnt++;
            }

    cnt = 1;
    for (i = 0; i < N; ++i)
        for (j = 0; j < N; ++j)
            if (isdigit(g1[i][j])) {
                k = g1[i][j] - '0';
                for (l = 1; l <= k; ++l) {
                    p.r = i; p.c = j; p.idx = cnt++;
                    BFS2(p);
                }
            }

    printf("%d\n", bipartite(cnt - 1));
    return 0;
}

bool augment(int u) {
    if (seen[u]) return false;
    seen[u] = 1;
    for (int i = 0; i < (int)graph[u].size(); ++i) {
        int v = graph[u][i];
        if (L[v] == -1) {
            L[v] = u;
            R[u] = i;
            return true;
        } else if (augment(L[v])) {
            L[v] = u;
            R[u] = i;
            return true;
        }
    }
    return false;
}

int bipartite(int m) {
    memset(L, -1, sizeof(L));
    memset(R, -1, sizeof(R));
    bool done;
    do {
        done = true;
        memset(seen, 0, sizeof(seen));
        for (int i = 1; i <= m; ++i)
            if (R[i] == -1 && augment(i))
                done = false;
    } while (!done);
    int ans = 0;
    for (int i = 1; i <= m; ++i)
        if (R[i] != -1) ++ans;
    return ans;
}

void BFS2(Point s) {
    int i, j, k, l;
    Point p, q;
    for (i = 0; i <= N; ++i)
        for (j = 0; j <= N; ++j)
            D2[i][j] = BIG;
    i = s.r; j = s.c;
    D2[i][j] = 0;
    Q.push(s);
    while (!Q.empty()) {
        p = Q.front(); Q.pop();
        i = p.r; j = p.c;
        if (D2[i][j] > T) continue;
        if (g1[i][j] == 'Y') continue;
        if (cells[i][j].used) {
            if (D2[i][j] <= T && D2[i][j] <= D1[i][j]) {
                for (k = 1; k <= cells[i][j].sz; ++k)
                    graph[s.idx].push_back(cells[i][j].nums[k]);
            }
        }
        if (D2[i][j] >= D1[i][j]) continue;
        // four directions
        int dr[] = {-1, 1, 0, 0};
        int dc[] = {0, 0, -1, 1};
        for (int d = 0; d < 4; ++d) {
            int nr = i + dr[d];
            int nc = j + dc[d];
            if (nr >= 0 && nr < N && nc >= 0 && nc < N) {
                if (D2[nr][nc] > D2[i][j] + 1) {
                    D2[nr][nc] = D2[i][j] + 1;
                    q.r = nr; q.c = nc;
                    Q.push(q);
                }
            }
        }
    }
}

void BFS1(Point s) {
    int i, j;
    Point p, q;
    i = s.r; j = s.c;
    D1[i][j] = 0;
    Q.push(s);
    while (!Q.empty()) {
        p = Q.front(); Q.pop();
        i = p.r; j = p.c;
        if (g1[i][j] == 'Y') continue;
        int dr[] = {-1, 1, 0, 0};
        int dc[] = {0, 0, -1, 1};
        for (int d = 0; d < 4; ++d) {
            int nr = i + dr[d];
            int nc = j + dc[d];
            if (nr >= 0 && nr < N && nc >= 0 && nc < N) {
                if (D1[nr][nc] > D1[i][j] + 1) {
                    D1[nr][nc] = D1[i][j] + 1;
                    q.r = nr; q.c = nc;
                    Q.push(q);
                }
            }
        }
    }
}
